void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    // Backtrack to root level
    backtrack(0);
    // Rephase variables with a more aggressive random strategy
    int r = rand() % 100;
    if (r < 30) {
        // Use the best local phase found so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 60) {
        // Use the opposite of the best local phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Randomly assign a phase
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
    // Optionally enlarge the restart threshold to delay immediate rephasing
    threshold = std::max(threshold, (int)trail.size() * 2);
}
